<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useResource,useTask,confirmAction} from '../composables/useData'
import {service,dataMode} from '../services'
import type {Faq} from '../types/domain'
import PageHeader from '../components/PageHeader.vue'
import LoadState from '../components/LoadState.vue'
import SafeMarkdown from '../components/SafeMarkdown.vue'
import Icon from '../components/Icon.vue'
const route=useRoute(),faqs=useResource('faqs'),task=useTask(),query=ref(''),filter=ref('pending_review'),dialog=ref(false),draft=ref<Faq>(),action=ref<'approve'|'reject'|'edit'>('approve')
const review=computed(()=>route.path.endsWith('recommendations'))
watch(review,v=>{filter.value=v?'pending_review':'published'},{immediate:true})
watch(faqs.items,value=>{if(draft.value&&!value.find(f=>f.id===draft.value?.id)?.answer){dialog.value=false;draft.value=undefined}})
const rows=computed(()=>faqs.items.value.filter(f=>(!query.value||`${f.question} ${f.category}`.includes(query.value))&&f.status===filter.value))
function open(faq:Faq,a:'approve'|'reject'|'edit'){draft.value=JSON.parse(JSON.stringify(faq));action.value=a;dialog.value=true}
async function submit(){if(!draft.value)return;await task.run(async()=>{if(action.value==='edit')await service.save('faqs',draft.value!);else await service.reviewFaq(draft.value!.id,action.value as 'approve'|'reject',draft.value!.answer);dialog.value=false;await faqs.load()},action.value==='approve'?'FAQ 已发布':action.value==='reject'?'推荐已驳回':'FAQ 已更新')}
async function offline(faq:Faq){if(!await confirmAction('下线后，此 FAQ 将停止用于缓存回答，返回待审核状态。','下线 FAQ'))return;await task.run(async()=>{await service.save('faqs',{...faq,status:'pending_review',cache:false});await faqs.load()},'FAQ 已下线')}
async function remove(faq:Faq){if(!await confirmAction('删除此 FAQ？对应缓存将同步失效。','删除 FAQ'))return;await task.run(async()=>{await service.remove('faqs',[faq.id]);await faqs.load()},'FAQ 已删除')}
</script>
<template><PageHeader :title="review?'FAQ 推荐审核':'已发布 FAQ'" :description="review?'从高频问题中沉淀标准答案，核对来源后再发布。':'维护已上线的标准问答与缓存状态。'"><button class="btn quiet" :disabled="faqs.loading.value" @click="faqs.load"><Icon name="refresh"/>刷新</button></PageHeader><form class="filters" @submit.prevent><label class="search"><Icon name="search"/><input v-model="query" placeholder="搜索问题或分类" aria-label="搜索 FAQ"></label><select v-if="review" v-model="filter" aria-label="FAQ 审核状态"><option value="pending_review">待审核</option><option value="rejected">已驳回</option></select><span v-else class="small faint">已发布 {{rows.length}} 项</span></form><LoadState :loading="faqs.loading.value" :error="faqs.error.value" :empty="!rows.length" :empty-text="review?'当前没有待处理的 FAQ 推荐。':'暂无已发布 FAQ，可先前往推荐审核。'" @retry="faqs.load"><div class="faq-grid"><article v-for="faq in rows" :key="faq.id" class="panel faq-card"><header><span class="status">{{faq.category}}</span><span class="small faint">{{review?`出现 ${faq.frequency} 次`:`缓存命中 ${faq.hits} 次`}}</span></header><h2>{{faq.question}}</h2><SafeMarkdown :content="faq.answer||'相关知识未授权或已删除，暂不可查看答案。'"/><div class="faq-source"><RouterLink v-if="faq.answer" :to="`/knowledge/units/${faq.unitId}`">查看关联知识 ↗</RouterLink><span v-if="!review" class="status" :class="faq.cache?'success':'warning'">{{dataMode==='demo'?'模拟缓存 · ':''}}{{faq.cache?'生效':'未生效'}}</span><span v-else class="status" :class="faq.status==='rejected'?'error':''">{{faq.status==='rejected'?'已驳回':'待审核'}}</span></div><footer v-if="review"><button class="btn quiet small" :disabled="!faq.answer||task.busy.value" @click="open(faq,'reject')">驳回</button><button class="btn small" :disabled="!faq.answer||task.busy.value" @click="open(faq,'approve')">编辑并审核发布</button></footer><footer v-else><button class="text-button" :disabled="!faq.answer" @click="open(faq,'edit')">编辑答案</button><button class="text-button" @click="offline(faq)">下线</button><button class="text-button danger" @click="remove(faq)">删除</button></footer></article></div></LoadState><el-dialog v-model="dialog" :title="action==='approve'?'审核并发布 FAQ':action==='reject'?'驳回推荐':'编辑 FAQ'" width="680px" :close-on-click-modal="false"><LoadState :loading="faqs.loading.value" :error="faqs.error.value" @retry="faqs.load"><form v-if="draft" id="faq-form" @submit.prevent="submit"><label class="field">问题<input v-model="draft.question" :readonly="action!=='edit'" maxlength="300" required></label><label class="field">标准答案<textarea v-model="draft.answer" rows="9" maxlength="20000" required :readonly="action==='reject'" /></label><p class="small muted" style="margin-top:18px">{{action==='reject'?'驳回后保留审核记录，不进入已发布库。':dataMode==='demo'?'本地演示：发布后参与模拟 FAQ 匹配，不写入真实 Redis 缓存。':'发布后由后端更新缓存，知识权限仍需校验。'}}</p><p v-if="task.error.value" class="field-error">{{task.error.value}}</p></form></LoadState><template #footer><button class="btn quiet" @click="dialog=false">取消</button><button class="btn primary" :disabled="task.busy.value||faqs.loading.value||!!faqs.error.value||!draft" form="faq-form">{{action==='approve'?'确认发布':action==='reject'?'确认驳回':'保存答案'}}</button></template></el-dialog></template>
<style scoped>.faq-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:start}.faq-card>header{display:flex;align-items:center;justify-content:space-between;gap:16px}.faq-card>h2{margin:22px 0 16px;font-size:18px}.faq-card :deep(.markdown){font-size:13px;color:var(--muted)}.faq-source{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:24px 0;font-size:12px}.faq-source>a{color:var(--accent)}.faq-card>footer{border-top:1px solid var(--line);padding-top:18px;display:flex;justify-content:flex-end;gap:10px}@media(max-width:640px){.faq-grid{grid-template-columns:1fr}.faq-card>h2{font-size:17px}.faq-card>footer{flex-wrap:wrap}}</style>
